import{_ as l,c as t,o as e,ag as i}from"./chunks/framework.DfL_BkQ-.js";const u=JSON.parse('{"title":"О сервере","description":"","frontmatter":{},"headers":[],"relativePath":"info/about.md","filePath":"info/about.md"}'),c={name:"info/about.md"};function r(s,o,n,d,a,g){return e(),t("div",null,[...o[0]||(o[0]=[i('<h1 id="о-сервере" tabindex="-1">О сервере <a class="header-anchor" href="#о-сервере" aria-label="Permalink to &quot;О сервере&quot;">​</a></h1><h2 id="▌-особенности-сервера" tabindex="-1">▌ Особенности сервера <a class="header-anchor" href="#▌-особенности-сервера" aria-label="Permalink to &quot;▌ Особенности сервера&quot;">​</a></h2><blockquote><ul><li><strong>Большой мир без вайпов</strong></li><li><strong>Гриферство запрещено в любых его проявлениях</strong></li><li><strong>Новые крафты</strong></li><li><strong>Аукцион и личные магазины</strong></li><li><strong>Минимальные цены для аукциона</strong></li><li><strong>Рисование пиксель-артов</strong></li><li><strong>Прорисовка 8 чанков</strong></li><li><strong>Выключена крыша ада</strong></li><li><strong>Титулы и значки</strong></li><li><strong>Создание гильдий и заключение браков</strong></li><li><strong>Ежедневные награды</strong></li></ul></blockquote><h2 id="▌-игровые-чаты" tabindex="-1">▌ Игровые чаты <a class="header-anchor" href="#▌-игровые-чаты" aria-label="Permalink to &quot;▌ Игровые чаты&quot;">​</a></h2><blockquote><p>Для удобства мы создали несколько игровых чатов:</p></blockquote><blockquote><p>▪ <strong>L</strong> — <strong>Локальный</strong> Сообщения видны в радиусе <strong>100</strong> блоков.</p><p>▪ <span style="color:#3b82f6;"><strong>G</strong></span> — <strong>Глобальный</strong> Сообщения видны всем во всех мирах. Нужно написать знак <strong>«!»</strong> перед текстом.</p><p>▪ <span style="color:#22c55e;"><strong>T</strong></span> — <strong>Торговый</strong> Виден везде, но используется только для продажи ресурсов. Нужно написать знак <strong>«$»</strong> перед текстом.</p></blockquote><h2 id="▌-доступные-команды" tabindex="-1">▌ Доступные команды <a class="header-anchor" href="#▌-доступные-команды" aria-label="Permalink to &quot;▌ Доступные команды&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Совет</p><p>Полный список команд всегда доступен в игре через <strong>/help</strong>.</p></div><blockquote><p><strong>Основные:</strong></p><ul><li><code>/rtp</code> — Рандомная телепортация</li><li><code>/spawn</code> — Телепорт на спавн</li><li><code>/menu</code> — Меню сервера</li><li><code>/donate</code> — Привилегии сервера</li><li><code>/kits</code> — Комплекты (киты)</li><li><code>/hdb</code> — Головы для декораций</li><li><code>/art</code> — Рисование</li></ul></blockquote><blockquote><p><strong>Дом и регионы:</strong></p><ul><li><code>/sethome</code> — Установить точку дома</li><li><code>/homes</code> — Меню с домами</li><li><code>/ps help</code> — Помощь по привату территорий</li><li><code>/ps get</code> — Получить защитный блок</li></ul></blockquote><blockquote><p><strong>Экономика:</strong></p><ul><li><code>/money</code> — Баланс монет</li><li><code>/pex</code> — Баланс пексов (донат-валюта)</li><li><code>/pay &lt;ник&gt; &lt;сумма&gt;</code> — Отправить игроку деньги</li><li><code>/baltop</code> — Топ игроков по балансу</li><li><code>/ah</code> — Аукцион</li></ul></blockquote><blockquote><p><strong>Взаимодействие:</strong></p><ul><li><code>/msg &lt;ник&gt;</code> — Личное сообщение</li><li><code>/r</code> — Ответ на последнее сообщение</li><li><code>/tpa &lt;ник&gt;</code> — Запрос на телепортацию к игроку</li><li><code>/ignore &lt;ник&gt;</code> — Игнорировать игрока</li><li><code>/ignorelist</code> — Список игнорируемых игроков</li><li><code>/discord</code> — Дискорд сервера</li></ul></blockquote><blockquote><p><strong>Эмоции и действия:</strong></p><ul><li><code>/sit</code> — Сесть на любой блок</li><li><code>/lay</code> — Лечь на любой блок</li><li><code>/crawl</code> — Ползти</li><li><code>/spin</code> — Крутиться</li><li><code>/premium</code> — Отметить аккаунт как лицензионный</li></ul></blockquote>',13)])])}const b=l(c,[["render",r]]);export{u as __pageData,b as default};
